-- 内部报价 P1: 业务手册 → 计算规则 becomes block-built (shared/fee_engine.py).
--
-- A rule version's content is now parameters people type plus a formula from a
-- fixed set of blocks, every number with its source, so a new kind of fee is
-- created in the back office without a release. Each version carries its fee's
-- display name. Versions in the old upstairs-only format that never took effect
-- are retired (the format can no longer be computed); the V6.1 first batch of
-- fees is added as drafts in the new format, to be checked against the manual,
-- trial-calculated and approved with the headquarters effective date.
-- agent_fee_quotes keeps every quote made from the back office or the robot.
ALTER TABLE agent_fee_rule_versions
    ADD COLUMN fee_name VARCHAR(40) NOT NULL DEFAULT '' AFTER fee_kind;

UPDATE agent_fee_rule_versions SET fee_name='上楼费' WHERE fee_kind='upstairs' AND fee_name='';

INSERT INTO agent_fee_rule_events (rule_id, action, actor_id, detail_json)
SELECT rule_id, 'RETIRE', 'migration:090', JSON_OBJECT('reason', '计算规则改为积木格式，旧格式草稿不再能计算（迁移 090）')
FROM agent_fee_rule_versions
WHERE status IN ('DRAFT', 'PENDING') AND JSON_EXTRACT(content_json, '$.schema') IS NULL;

UPDATE agent_fee_rule_versions
SET status='RETIRED', retired_by='migration:090', retired_at=UTC_TIMESTAMP(6), updated_by='migration:090',
    row_version=row_version+1
WHERE status IN ('DRAFT', 'PENDING') AND JSON_EXTRACT(content_json, '$.schema') IS NULL;

